": 공식 발표 예정일보다 하루 넘게 지났는데 새 자료가 없으면 “늦음”이에요. 미국 공휴일·정부 셧다운 때는 기관이 공식적으로 미뤄요. 이때도 값을 추정해 채우지 않아요.": "：若已超過官方預定公布日一天以上仍無新資料，就標示為「延遲」。美國假日或政府關門時，機構會正式延後。即使如此，我們也不會推估或填補數值。",
": 관측일은 자료가 가리키는 날, 발표일은 기관이 공개한 날이에요. CFTC는 화요일 기준을 금요일에 공개해서 {0}일 차이가 정상이에요.": "：觀察日是資料所指的日期，公布日是機構公開的日期。CFTC 在週五公布週二的資料，因此相差{0}天屬正常。",
": 기관이 과거 숫자를 고치면, 이전 값을 지우지 않고 새 값과 함께 남겨요.": "：機構修正過去的數字時，我們不會刪除舊值，而是與新值一併保留。",
": 뉴욕 연은이 지정한 국채 딜러(증권회사). 모든 입찰에 합리적 가격으로 참여할 의무": "：由紐約聯準銀行指定的公債交易商（證券商），有義務在每場標售中以合理價格參與投標",
": 발행 예정 금액보다 약 {0}배 많은 자금이 응찰": "：投標資金約為預定發行金額的 {0} 倍",
": 위 선은 투기자금, 아래 선은 가격이에요. 두 선이 같이 오르내리면 돈이 가격을 밀고 있는 것, 엇갈리면 가격과 돈의 생각이 다른 거예요.": "：上方的線是投機資金，下方的線是價格。兩條線一起漲跌，代表資金在推動價格；走勢分歧，則代表價格與資金看法不一。",
": 입찰 부진 + 유동성 악화가 동시에": "：標售疲弱與流動性惡化同時發生",
": 장기금리가 무서워 단기물로 버티면({0}년 옐런의 Bills Pivot), 금리가 높은 상태가 길어질수록 매년 갚아야 할 이자가 빠르게 늘어요. {1}년 안에 만기가 오는 중기채까지 더하면 실제 부담은 이보다 커요.": "：若財政部因害怕長期殖利率而改靠短期債撐著（{0} 年葉倫的 Bills Pivot），殖利率維持高檔越久，每年要付的利息就增加得越快。再加上 {1} 年內到期的中期債，實際負擔會比這個數字更大。",
": 주황 선(올해)이 파란 띠(지난 {0}년 범위) 아래에 있으면 공급이 빠듯, 위에 있으면 넉넉해요.": "：橘線（今年）低於藍色區帶（過去{0}年的範圍），代表供給吃緊；高於區帶則代表充裕。",
": 주황 점이 이번 주 위치예요. 오른쪽 위(① 추세 매수)·왼쪽 아래(④ 매도 추세)는 가격과 돈이 같은 방향, 나머지 두 칸은 엇갈린 상태예요. 회색 점선은 지난 {0}주 동안 어디를 지나왔는지예요.": "：橘色點是本週的位置。右上（① 趨勢買進）與左下（④ 賣壓趨勢）代表價格與資金同方向，另外兩格則代表兩者背離。灰色虛線是過去{0}週走過的軌跡。",
