"“가장 비싸고, 가장 먼 미래를 반영한 자산부터 무너진다”": "「最貴、反映最遙遠未來的資產，最先崩跌」",
"“국채가 위험해서 금리가 오르는 게 아니라, 시장에 나온 물량을 받아줄 대차대조표가 부족해서 금리가 오를 수도 있다.”": "「殖利率上升，未必是因為公債有風險，也可能是因為資產負債表不足以承接市場上的供給量。」",
"“늦음”은 공식 발표 예정일보다 하루 넘게 지났는데 새 자료가 없다는 뜻이에요 (미국 공휴일·정부 셧다운 때는 공식적으로 밀려요). 늦어도 값을 이어 붙이거나 추정하지 않아요.": "「延遲」代表已超過官方預定公布日一天以上仍無新資料（美國假日與政府關門時會正式延後）。即使延遲，我們也不會拼接或推估數值。",
"“반대 근거”에 적어 둬요. 한쪽 신호만 보고 결론 내리지 않도록요.": "會寫在「反面證據」裡，避免只看單一訊號就下結論。",
