"“유동성”·“시장 기능”을 언급할 때": "當它提到「流動性」或「市場運作」時",
"“재무부가 단기물 발행을 늘릴 때는, 돈이 필요한 것보다 장기금리가 더 무서운 상태인 경우가 많다.”": "「財政部增加短期債發行時，往往是因為比起缺錢，更害怕長期殖利率。」",
