"가 붙은 건 공식 가격이 없어 선물 시세로 계산한 비율이에요.": "標示代表沒有官方價格，是用期貨報價算出來的比率。",
"가 오르면 이자를 현금으로 못 받는 대출이 늘어난 것": " 上升代表無法以現金收取利息的放款增加",
"가 줄면 펀드가 새 대출·환매에 쓸 돈이 줄어요. 기준: PIK {0}%↑ 주의": " 減少代表基金可用於新放款與贖回的資金變少。標準：PIK {0}%↑ 注意",
"가격": "價格",
"가격 ($": "價格（$",
"가격 (공식)": "價格（官方）",
"가격 {0}주": "價格 {0}週",
"가격 {0}주:": "價格 {0}週：",
"가격 × 투기자금": "價格 × 投機資金",
"가격 ↑": "價格 ↑",
