"가격 방향과 투기자금 방향을 짝지어 {0}가지 중 하나로 읽어요 (예: “④ 매도 추세 확인”). 자세한 근거는 카드를 눌러 보세요.": "把價格方向與投機資金方向配對，歸為{0}種情況之一（例如「④ 賣壓趨勢確認」）。點選卡片可看詳細依據。",
"가격 변화와 투기자금 변화 사분면": "價格變化與投機資金變化的四象限圖",
"가격 숫자는 공식 자료(EIA·IMF)만 실어요. 공식 무료 가격이 없는 금·은·백금·리튬은 가격 숫자를 싣지 않아요.": "價格數字只採用官方資料（EIA、IMF）。黃金、白銀、鉑金、鋰沒有官方免費價格，因此不顯示價格數字。",
"가격 숫자는 싣지 않음": "不顯示價格數字",
"가격 위험을 줄이려고(헤지) 거래해요. 보통 생산자라 숏이 많아요.": "他們交易是為了降低價格風險（避險）。通常是生產商，因此多半持有較多空單。",
"가격 자료가 {0}일 지났어요": "價格資料已過 {0} 天",
"가격 하락": "價格下跌",
"가격 흐름 지수 ({0}년 전 = {1} Yahoo 선물 기준": "價格走勢指數（{0}年前＝{1}，以 Yahoo 期貨為準",
"가격 흐름을 따라 빠르게 움직여 “돈의 쏠림”을 보여 줘요.": "會隨價格走勢快速移動，因此能看出「資金的擠壓方向」。",
"가격(관측)": "價格（觀察日）",
"가격↑": "價格↑",
"가격과 돈이 같은 방향이면 흐름이 단단하고, 엇갈리면 지속성을 의심해요.": "價格與資金同方向時，趨勢較穩固；兩者背離時，就要懷疑持續性。",
"가격만 보면 “왜 움직였는지”를 알 수 없어요. 돈의 쏠림(포지션)과 실물 상황(재고)을 같이 보면 그 움직임이 오래갈지, 일시적인지 가늠할 수 있어요.": "只看價格，看不出「為什麼會動」。把資金的擁擠程度（持倉）和實物狀況（庫存）一起看，就能判斷這波走勢會持續還是只是一時。",
"가격은 약세인데 재고는 {0}년 평균보다 적어요 — 실물은 빠듯해 반등 여지가 있어요.": "價格偏弱,但庫存低於 {0} 年平均 — 實體供給吃緊,有反彈空間。",
"가격은 오름세인데 재고는 {0}년 평균보다 많아요 — 실물이 받쳐 주지 않는 상승일 수 있어요.": "價格呈上升趨勢,但庫存高於 {0} 年平均 — 這可能是缺乏實體支撐的上漲。",
"가격은 올랐지만 투기자금은 오히려 줄였어요": "價格上漲，但投機資金反而減碼",
"가격은 올랐지만 투기자금은 오히려 줄였어요 — 숏 커버(빌려 판 것 되사기)나 실수요가 끌어올린 상승일 수 있어 지속되는지 확인이 필요해요.": "價格上漲,但投機資金反而減碼 — 這波上漲可能是空單回補(回頭買回先前借來賣掉的部位)或實際需求者推升,需確認能否持續。",
"가격을 맞히려는 화면이 아니라, 가격을 움직이는 구조": "不是用來猜價格的頁面，而是看價格背後的結構：",
"가격이 내리고 투기자금도 빠져나갔어요": "價格下跌，投機資金也撤出",
"가격이 내리고 투기자금도 빠져나갔어요 — 하락 흐름을 돈이 확인해 주는 모습이에요.": "價格下跌,投機資金也跟著撤出 — 資金印證了下跌趨勢。",
"가격이 내리는데 투기자금은 더 샀어요 — 바닥을 찾는 매수일 수도, 성급한 매수일 수도 있어요.": "價格下跌,投機資金卻加碼買進 — 可能是在找底的買盤,也可能只是太早進場。",
"가격이 오르는데 투기자금도 더 샀어요 — 상승을 돈이 따라붙는 모습이에요.": "價格上漲,投機資金也加碼買進 — 資金跟著上漲趨勢進場。",
"가로 = 그 주 가격 변화(%), 세로 = 투기자금 순매수 변화(미결제약정 대비 %). 회색 점선은 지난 {0}주 궤적, 주황 점이 이번 주. 가운데 회색 띠(±{1}%)는 “변화 거의 없음”.": "橫軸＝當週價格變化（%），縱軸＝投機資金淨買超變化（占未平倉量 %）。灰色虛線是過去 {0} 週的軌跡，橘色點是本週。中間灰色帶（±{1}%）代表「幾乎沒有變化」。",
