"미국 CFTC가 매주 금요일 공개하는 선물 포지션 보고서. 그 주 화요일 기준이에요.": "美國 CFTC 每週五公布的期貨持倉報告，以該週週二為基準。",
"미국 CFTC에 있는 알루미늄 계약은 알루미늄 값이 아니라 미국 중서부에서 붙는 '웃돈(Midwest Premium)' 계약이에요. 이 포지션을 알루미늄 투기 흐름으로 읽으면 오해할 수 있어 기본으로 숨겨요.": "美國 CFTC 的鋁合約並不是鋁價本身,而是美國中西部加收的「溢價(Midwest Premium)」合約。把這個持倉當成鋁的投機動向容易造成誤解,因此預設隱藏。",
