"선물 시장에는 실제로 원자재를 쓰는 회사(생산·실수요)와, 가격 흐름에 돈을 거는 투기자금이 함께 있어요. 미국 CFTC는 매주 “누가 얼마나 사고팔아 두었는지”를 공개해요. 투기자금이 한쪽으로 크게 몰리면 가격이 그 방향으로 밀리기도 하지만, 너무 몰리면 되돌아갈 때 크게 출렁여요.": "期貨市場裡，同時有實際使用原物料的公司（生產商與實際需求者），以及押注價格走勢的投機資金。美國 CFTC 每週公布「誰買了多少、賣了多少」。投機資金大量集中在單邊時，可能把價格推向那個方向，但太擁擠的話，反轉時波動會很劇烈。",
